  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","mode","color","accent","copies","fontSize","fontWeight","outline","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Repeat",
  mode: "tunnel",
  color: "#111111",
  accent: "#fafafa",
  copies: 12,
  fontSize: 110,
  fontWeight: 800,
  outline: true,
  speed: 1,
};

type TypeRepeaterElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TypeRepeaterBase>;

const TypeRepeaterInner = forwardRef<
  HTMLDivElement,
  TypeRepeaterElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TypeRepeater>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TypeRepeaterBase
          {...(componentProps as unknown as ComponentProps<typeof TypeRepeaterBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TypeRepeater = Interactive.withSchema({
  Component: TypeRepeaterInner,
  componentName: "<TypeRepeater>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
